-- University photos (Wikimedia Commons, free licences) + descriptions (Wikipedia).
alter table public.universities add column if not exists image_url text;
alter table public.universities add column if not exists about text;

update public.universities set image_url = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/Old_Arts_Building_University_of_Melbourne_2018.jpg/1920px-Old_Arts_Building_University_of_Melbourne_2018.jpg', about = 'The University of Melbourne (UniMelb) is a public research university located in Melbourne, Australia. Founded in 1853, it is Australia''s second oldest university and the oldest in the state of Victoria. Its main campus is located in Parkville, an inner suburb north of Melbourne''s central business district, with several other campuses located across the state of Victoria.' where name = 'University of Melbourne';
update public.universities set image_url = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/The_University_of_Sydney%27s_Main_Quadrangle.jpg/1920px-The_University_of_Sydney%27s_Main_Quadrangle.jpg', about = 'The University of Sydney (USYD) is a public research university in Sydney, Australia. Founded in 1850, it is the oldest university in both Australia and Oceania. One of Australia''s six sandstone universities, it was one of the world''s first universities to admit students solely on academic merit, and opened its doors to women on the same basis as men. The university comprises eight academic faculties and university schools, through which it offers bachelor, master and doctoral degrees.' where name = 'University of Sydney';
update public.universities set image_url = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Main_Walkway%2C_Lower_campus_UNSW.jpg/1920px-Main_Walkway%2C_Lower_campus_UNSW.jpg', about = 'The University of New South Wales (UNSW) is a public research university based in Sydney, New South Wales, Australia. It was established in 1949.' where name = 'UNSW Sydney';
update public.universities set image_url = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Monash_University_Clayton_Campus.jpg/1920px-Monash_University_Clayton_Campus.jpg', about = 'Monash University is a public research university based in Melbourne, Victoria, Australia. Named after World War I general Sir John Monash, it was founded in 1958. The university has a number of campuses, four of which are in Victoria, one in Malaysia and another one in Indonesia. Monash has a research and teaching centre in Prato, Italy, a graduate research school in Mumbai, India, and graduate schools in Suzhou, China, and Tangerang, Indonesia.' where name = 'Monash University';
update public.universities set image_url = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/University_House_ANU_Canberra_%282948649223%29.jpg/1920px-University_House_ANU_Canberra_%282948649223%29.jpg', about = 'The Australian National University (ANU) is a public research university and member of the Group of Eight, located in Canberra, the capital of Australia. Its main campus in Acton encompasses seven teaching and research colleges, in addition to several national academies and institutes.' where name = 'Australian National University';
update public.universities set image_url = 'https://upload.wikimedia.org/wikipedia/commons/d/d1/Dr_Chau_Chak_Wing_Building.jpg', about = 'The University of Technology Sydney (UTS) is a public research university located in Sydney, New South Wales, Australia. The university was founded in its current form in 1988, though its origins as a technical institution can be traced back to the 1870s. UTS is a founding member of the Australian Technology Network (ATN), and is a member of Universities Australia (UA) and the Worldwide Universities Network (WUN).' where name = 'University of Technology Sydney';
update public.universities set image_url = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Advanced_Engineering_Building_and_Lake_at_the_University_of_Queensland%2C_St_Lucia_Campus%2C_2020.jpg/1920px-Advanced_Engineering_Building_and_Lake_at_the_University_of_Queensland%2C_St_Lucia_Campus%2C_2020.jpg', about = 'The University of Queensland (UQ) is a public research university located primarily in Brisbane, the capital city of the Australian state of Queensland. Established in 1909 by an act of the Queensland Parliament, UQ is one of the six sandstone universities; an informal designation for the oldest university in each state. UQ is also a founding member of edX, the Group of Eight and the international research-intensive Association of Pacific Rim Universities.' where name = 'University of Queensland';
update public.universities set image_url = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/The_Mitchell_Building_on_the_University_of_Adelaide_campus_on_North_Terrace._-_24599815649.jpg/1920px-The_Mitchell_Building_on_the_University_of_Adelaide_campus_on_North_Terrace._-_24599815649.jpg', about = 'The University of Adelaide (UofA) was a public research university based in Adelaide, South Australia. Established in 1874, it was the third-oldest university in Australia. Its main campus in the Adelaide city centre included many sandstone buildings of historical and architectural significance, such as Bonython Hall. Its royal charter awarded by Queen Victoria in 1881 allowed it to become the second university in the English-speaking world to confer degrees to women. On 5 January 2026, it merged with the neighbour' where name = 'University of Adelaide';
update public.universities set image_url = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/Shenton_House%2C_University_of_Western_Australia%2C_December_2021_02.jpg/1920px-Shenton_House%2C_University_of_Western_Australia%2C_December_2021_02.jpg', about = 'The University of Western Australia (UWA) is a public research university in Crawley, Western Australia, Australia. UWA was established in 1911 by an act of the Parliament of Western Australia.' where name = 'University of Western Australia';
update public.universities set image_url = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/RMIT_University_City_Campus.jpg/1920px-RMIT_University_City_Campus.jpg', about = 'The Royal Melbourne Institute of Technology is a public research university located in the city of Melbourne in Victoria, Australia. Proposed by Francis Ormond, and established in 1887 by Ormond, the Victorian government, Trades Hall Council and others, it is the seventh-oldest institution of higher education in Australia, a founding member of the Australian Technology Network (ATN), and a member of Universities Australia (UA).' where name = 'RMIT University';
update public.universities set image_url = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e9/Aerial_photo_of_Deakin_University%27s_Building_C.jpg/1920px-Aerial_photo_of_Deakin_University%27s_Building_C.jpg', about = 'Deakin University is a public research university in the state of Victoria, Australia. Its largest campus is in Victoria''s state capital Melbourne, with regional campuses in Geelong and Warrnambool. The university was named after Alfred Deakin, the early Prime Minister of Australia and a founding father of Australian Federation.' where name = 'Deakin University';
update public.universities set image_url = 'https://upload.wikimedia.org/wikipedia/commons/d/d9/Macquarie_University.jpg', about = 'Macquarie University is a public research university in Sydney, New South Wales, Australia. Founded in 1964 by the New South Wales Government, it was the third university to be established in the Sydney metropolitan area.' where name = 'Macquarie University';
